// Clique direto na bolinha de status cicla Livre → Obstruído → Varado → Livre,
// sem precisar abrir o modal de edição só pra isso — mais rápido num turno corrido.
const ORDEM_SITUACAO = ['livre', 'obstruido', 'varado'];
function ciclarSituacaoFuro(id){
  const f = furos.find(x=>x.id===id);
  if(!f) return;
  const l = leques.find(x=>x.id===f.lequeId);
  if(!souDonoDoLeque(l)){
    showToast('Só quem criou este leque pode editar os furos dele.');
    return;
  }
  const proxima = ORDEM_SITUACAO[(ORDEM_SITUACAO.indexOf(f.situacao) + 1) % ORDEM_SITUACAO.length];
  f.situacao = proxima;
  enfileirar('furos', 'update', { id: f.id, situacao: proxima });
  salvarLocal();
  renderAll();
  showToast(`${furoCode(l,f)}: ${situacaoLabel(proxima)}.`);
}

function editarFuro(id){
  const f = furos.find(x=>x.id===id);
  if(!f) return;
  const l = leques.find(x=>x.id===f.lequeId);
  if(!souDonoDoLeque(l)){
    showToast('Só quem criou este leque pode editar os furos dele.');
    return;
  }
  editFuroModal(f).then(resultado=>{
    if(!resultado) return;
    if(resultado.numero !== f.numero){
      const duplicado = furos.some(x=>x.lequeId===f.lequeId && x.numero===resultado.numero && x.id!==f.id);
      if(duplicado){
        showToast(`Já existe o furo ${l ? lequeCode(l) : ''}F${resultado.numero} neste leque.`);
        return;
      }
    }
    f.numero = resultado.numero;
    f.metragemEsperada = resultado.metragemEsperada;
    f.metragemReal = resultado.metragemReal;
    f.situacao = resultado.situacao;
    enfileirar('furos', 'update', {
      id: f.id, numero: f.numero, metragem_esperada: f.metragemEsperada, metragem_real: f.metragemReal, situacao: f.situacao
    });
    salvarLocal();
    renderAll();
    showToast('Furo atualizado.');
  });
}

